def post(xs, target, result):
    if not isinstance(result, bool):
        return False

    max_len = min(8, len(xs))
    found_pair_sum = any(x + y == target and x != y for i in range(max_len) for j in range(i + 1, min(max_len, len(xs))) for x in (xs[i],) for y in (xs[j],))

    return result == found_pair_sum
